"""Writes the generated C# layer (src/Didit/Generated) from the model."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Any

from . import names
from .model import REQUEST, RESPONSE, EnumDef, Model, ObjectDef, Operation, Param, Prop, TypeRef

HEADER = (
    "// <auto-generated/>\n"
    "// Code generated by codegen from openapi/*.json. DO NOT EDIT.\n"
    "#nullable enable\n"
)

VALUE_KINDS = {"long", "double", "bool", "datetime"}
METHOD_FIELDS = {"GET": "Get", "POST": "Post", "PUT": "Put", "PATCH": "Patch", "DELETE": "Delete", "HEAD": "Head", "OPTIONS": "Options"}


# ---- documentation ------------------------------------------------------------------------------------------------

_CODE_RE = re.compile(r"`([^`]+)`")
_LINK_RE = re.compile(r"\[([^\]]+)\]\((https?://[^)\s]+)\)")
_BOLD_RE = re.compile(r"\*\*([^*]+)\*\*")


def xml_escape(text: str) -> str:
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def doc_text(text: str | None) -> list[str]:
    """Markdown description to XML doc lines."""
    if not text:
        return []
    text = text.replace("\r\n", "\n").strip()
    text = xml_escape(text)
    text = _CODE_RE.sub(lambda m: f"<c>{m.group(1)}</c>", text)
    text = _LINK_RE.sub(lambda m: f'<see href="{m.group(2)}">{m.group(1)}</see>', text)
    text = _BOLD_RE.sub(lambda m: m.group(1), text)
    lines: list[str] = []
    for paragraph in re.split(r"\n\s*\n", text):
        paragraph_lines = [line.rstrip() for line in paragraph.split("\n") if line.strip()]
        if not paragraph_lines:
            continue
        if lines:
            lines.append("<para/>")
        lines.extend(paragraph_lines)
    return lines


def summary(lines: list[str], indent: str, fallback: str) -> list[str]:
    body = lines or [xml_escape(fallback)]
    return [f"{indent}/// <summary>"] + [f"{indent}/// {line}" for line in body] + [f"{indent}/// </summary>"]


def cs_string(value: str) -> str:
    return json.dumps(value, ensure_ascii=False).replace("\\/", "/")


def is_file(ref: TypeRef) -> bool:
    return ref.kind == "file" or (ref.kind == "list" and ref.item is not None and ref.item.kind == "file")


def obsolete_message(op: Operation) -> str:
    removed_on = op.raw.op.get("x-didit-removed-on")
    if removed_on:
        return f"Removed from the Didit API on {removed_on}. This method is deleted in the next minor release."
    return "Deprecated by the Didit API."


# ---- types --------------------------------------------------------------------------------------------------------


@dataclass
class TypeInfo:
    model: Model

    def is_value_type(self, ref: TypeRef, role: str) -> bool:
        if ref.kind in VALUE_KINDS:
            return True
        if ref.kind == "any":
            return role == RESPONSE
        if ref.kind == "named":
            return ref.name in self.model.enums
        return False

    def base(self, ref: TypeRef, role: str) -> str:
        kind = ref.kind
        if kind == "string":
            return "string"
        if kind == "long":
            return "long"
        if kind == "double":
            return "double"
        if kind == "bool":
            return "bool"
        if kind == "datetime":
            return "DateTimeOffset"
        if kind == "file":
            return "FileUpload"
        if kind == "any":
            return "JsonElement" if role == RESPONSE else "object"
        if kind == "named":
            assert ref.name
            return ref.name
        if kind == "list":
            assert ref.item
            return f"IReadOnlyList<{self.element(ref.item, role)}>"
        if kind == "map":
            assert ref.item
            return f"IReadOnlyDictionary<string, {self.element(ref.item, role)}>"
        raise ValueError(kind)

    def element(self, ref: TypeRef, role: str) -> str:
        base = self.base(ref, role)
        if ref.kind == "any" and role == RESPONSE:
            return base
        return base + "?" if ref.nullable else base

    def nullable(self, ref: TypeRef, role: str) -> str:
        return self.base(ref, role) + "?"


# ---- emitter ------------------------------------------------------------------------------------------------------


@dataclass
class ResourceNode:
    segments: list[str]
    children: dict[str, "ResourceNode"] = field(default_factory=dict)
    operations: list[Operation] = field(default_factory=list)

    @property
    def type_name(self) -> str:
        return names.resource_type_name(self.segments) + "Resource"

    @property
    def raw_type_name(self) -> str:
        return names.resource_type_name(self.segments) + "RawResource"

    @property
    def accessor(self) -> str:
        return names.pascal(self.segments[-1])


class Emitter:
    def __init__(self, model: Model) -> None:
        self.model = model
        self.types = TypeInfo(model)
        self.files: dict[str, str] = {}

    def emit(self) -> dict[str, str]:
        for obj in self.model.objects.values():
            self.files[f"src/Didit/Generated/Models/{obj.name}.g.cs"] = self.object_file(obj)
        for enum in self.model.enums.values():
            self.files[f"src/Didit/Generated/Models/{enum.name}.g.cs"] = self.enum_file(enum)
        root = self.resource_tree()
        for node in self.walk(root):
            if node.segments:
                self.files[f"src/Didit/Generated/Resources/{node.type_name}.g.cs"] = self.resource_file(node)
        self.files["src/Didit/Generated/DiditClient.g.cs"] = self.client_file(root)
        self.files["src/Didit/Generated/DiditJsonContext.g.cs"] = self.context_file()
        return self.files

    # ---- models -------------------------------------------------------------------------------------------------

    def object_file(self, obj: ObjectDef) -> str:
        out = [HEADER, "using System;", "using System.Collections.Generic;", "using System.Text.Json;", "using System.Text.Json.Serialization;", "", "namespace Didit", "{"]
        description = doc_text(obj.description)
        fallback = f"Request body of {obj.origin}." if obj.role == REQUEST else f"Response object ({obj.origin})."
        out += summary(description, "    ", fallback)
        out.append(f"    public sealed record {obj.name}")
        out.append("    {")
        first = True
        for prop in obj.props:
            if not first:
                out.append("")
            first = False
            out += self.property(obj, prop)
        if not first:
            out.append("")
        out.append("        /// <summary>Fields not described by this SDK version, kept as raw JSON (sent with requests, filled from responses).</summary>")
        out.append("        [JsonExtensionData]")
        out.append("        public IDictionary<string, JsonElement>? AdditionalProperties { get; set; }")
        out.append("    }")
        out.append("}")
        return "\n".join(out) + "\n"

    def property(self, obj: ObjectDef, prop: Prop) -> list[str]:
        lines = summary(doc_text(prop.description), "        ", f"The <c>{prop.json_name}</c> field.")
        if prop.deprecated:
            lines.append("        [Obsolete(\"Deprecated by the API.\")]")
        lines.append(f"        [JsonPropertyName({cs_string(prop.json_name)})]")
        t = self.types
        if obj.role == RESPONSE:
            lines.append(f"        public {t.nullable(prop.type, RESPONSE)} {prop.cs_name} {{ get; init; }}")
            return lines
        if prop.location == "query":
            lines.append("        [JsonIgnore]")
            if prop.required:
                lines.append(f"        public required {t.base(prop.type, REQUEST)} {prop.cs_name} {{ get; set; }}")
            else:
                lines.append(f"        public {t.nullable(prop.type, REQUEST)} {prop.cs_name} {{ get; set; }}")
            return lines
        if is_file(prop.type):
            # Files travel only as multipart parts, never in a JSON body.
            lines.append("        [JsonIgnore]")
            if prop.required:
                lines.append(f"        public required {t.base(prop.type, REQUEST)} {prop.cs_name} {{ get; set; }}")
            else:
                inner = t.nullable(prop.type, REQUEST) if prop.nullable else t.base(prop.type, REQUEST)
                lines.append(f"        public Optional<{inner}> {prop.cs_name} {{ get; set; }}")
            return lines
        if prop.required:
            if prop.nullable:
                lines.append("        [JsonIgnore(Condition = JsonIgnoreCondition.Never)]")
                lines.append(f"        public required {t.nullable(prop.type, REQUEST)} {prop.cs_name} {{ get; set; }}")
            else:
                lines.append(f"        public required {t.base(prop.type, REQUEST)} {prop.cs_name} {{ get; set; }}")
            return lines
        inner = t.nullable(prop.type, REQUEST) if prop.nullable else t.base(prop.type, REQUEST)
        lines.append("        [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingDefault)]")
        lines.append(f"        public Optional<{inner}> {prop.cs_name} {{ get; set; }}")
        return lines

    def enum_file(self, enum: EnumDef) -> str:
        name = enum.name
        out = [HEADER, "using System;", "using System.Text.Json.Serialization;", "using Didit.Internal;", "", "namespace Didit", "{"]
        description = doc_text(enum.description)
        out += summary(description, "    ", f"Values of {enum.origin}.")
        out.append("    /// <remarks>An open enumeration: values added to the API later are accepted and kept as strings.</remarks>")
        out.append(f"    [JsonConverter(typeof({name}.EnumJsonConverter))]")
        out.append(f"    public readonly struct {name} : IStringEnum, IEquatable<{name}>")
        out.append("    {")
        out.append("        private readonly string? _value;")
        out.append("")
        out.append(f"        /// <summary>Creates a value. Any string is accepted.</summary>")
        out.append(f"        public {name}(string value)")
        out.append("        {")
        out.append("            _value = value ?? throw new ArgumentNullException(nameof(value));")
        out.append("        }")
        reserved = {"Value", "Equals", "GetHashCode", "ToString", "EnumJsonConverter", "GetType", name}
        used: set[str] = set()
        for value in enum.values:
            member = names.enum_member_name(value)
            if member in reserved:
                member += "Member"
            base_member = member
            index = 2
            while member in used:
                member = f"{base_member}{index}"
                index += 1
            used.add(member)
            out.append("")
            out.append(f"        /// <summary><c>{xml_escape(value)}</c></summary>")
            out.append(f"        public static {name} {member} {{ get; }} = new({cs_string(value)});")
        out.append("")
        out.append("        /// <summary>The wire value.</summary>")
        out.append("        public string Value => _value ?? string.Empty;")
        out.append("")
        out.append(f"        /// <summary>Converts a string into a value.</summary>")
        out.append(f"        public static implicit operator {name}(string value) => new(value);")
        out.append("")
        out.append("        /// <summary>Equality.</summary>")
        out.append(f"        public static bool operator ==({name} left, {name} right) => left.Equals(right);")
        out.append("")
        out.append("        /// <summary>Inequality.</summary>")
        out.append(f"        public static bool operator !=({name} left, {name} right) => !left.Equals(right);")
        out.append("")
        out.append("        /// <inheritdoc />")
        out.append(f"        public bool Equals({name} other) => string.Equals(Value, other.Value, StringComparison.Ordinal);")
        out.append("")
        out.append("        /// <inheritdoc />")
        out.append(f"        public override bool Equals(object? obj) => obj is {name} other && Equals(other);")
        out.append("")
        out.append("        /// <inheritdoc />")
        out.append("        public override int GetHashCode() => StringComparer.Ordinal.GetHashCode(Value);")
        out.append("")
        out.append("        /// <inheritdoc />")
        out.append("        public override string ToString() => Value;")
        out.append("")
        out.append(f"        internal sealed class EnumJsonConverter : StringEnumJsonConverter<{name}>")
        out.append("        {")
        out.append(f"            protected override {name} Create(string value) => new(value);")
        out.append("        }")
        out.append("    }")
        out.append("}")
        return "\n".join(out) + "\n"

    # ---- resources ----------------------------------------------------------------------------------------------

    def resource_tree(self) -> ResourceNode:
        root = ResourceNode([])
        for op in self.model.operations:
            node = root
            for index, segment in enumerate(op.resource):
                node = node.children.setdefault(segment, ResourceNode(op.resource[: index + 1]))
            node.operations.append(op)
        return root

    def walk(self, node: ResourceNode):
        yield node
        for key in sorted(node.children):
            yield from self.walk(node.children[key])

    def resource_file(self, node: ResourceNode) -> str:
        out = [HEADER, "using System;", "using System.Collections.Generic;", "using System.Linq;", "using System.Text.Json;", "using System.Threading;", "using System.Threading.Tasks;", "using Didit.Internal;", "", "namespace Didit.Resources", "{"]
        dotted = ".".join(node.segments)
        out.append(f"    /// <summary>The <c>{dotted}</c> resource.</summary>")
        out.append(f"    public sealed partial class {node.type_name}")
        out.append("    {")
        out.append(f"        private readonly {node.raw_type_name} _raw;")
        out.append("")
        out.append(f"        internal {node.type_name}({node.raw_type_name} raw)")
        out.append("        {")
        out.append("            _raw = raw;")
        for key in sorted(node.children):
            child = node.children[key]
            out.append(f"            {child.accessor} = new {child.type_name}(raw.{child.accessor});")
        out.append("        }")
        for key in sorted(node.children):
            child = node.children[key]
            out.append("")
            out.append(f"        /// <summary>The <c>{'.'.join(child.segments)}</c> resource.</summary>")
            out.append(f"        public {child.type_name} {child.accessor} {{ get; }}")
        for op in sorted(node.operations, key=lambda o: o.method):
            out.append("")
            out += self.method(op, raw=False)
        out.append("    }")
        out.append("")
        out.append(f"    /// <summary>The <c>{dotted}</c> resource, returning raw HTTP responses (<see cref=\"DiditResponse{{T}}\"/>).</summary>")
        out.append(f"    public sealed partial class {node.raw_type_name}")
        out.append("    {")
        out.append("        private readonly HttpPipeline _pipeline;")
        out.append("")
        out.append(f"        internal {node.raw_type_name}(HttpPipeline pipeline)")
        out.append("        {")
        out.append("            _pipeline = pipeline;")
        for key in sorted(node.children):
            child = node.children[key]
            out.append(f"            {child.accessor} = new {child.raw_type_name}(pipeline);")
        out.append("        }")
        for key in sorted(node.children):
            child = node.children[key]
            out.append("")
            out.append(f"        /// <summary>The <c>{'.'.join(child.segments)}</c> resource.</summary>")
            out.append(f"        public {child.raw_type_name} {child.accessor} {{ get; }}")
        for op in sorted(node.operations, key=lambda o: o.method):
            out.append("")
            out += self.method(op, raw=True)
        out.append("    }")
        out.append("}")
        return "\n".join(out) + "\n"

    def response_type(self, op: Operation) -> str | None:
        response = op.response
        if response.kind == "none":
            return None
        if response.kind == "binary":
            return "BinaryResponse"
        assert response.type is not None
        if response.kind == "page":
            return f"Page<{self.types.element(response.type, RESPONSE)}>"
        return self.types.base(response.type, RESPONSE)

    def body_arg(self, op: Operation) -> tuple[str, str, bool] | None:
        """(type, name, required) of the body or Params argument."""
        t = self.types
        if op.params_type is not None:
            obj = self.model.objects[op.params_type]
            required = any(p.required for p in obj.props) or (op.body is not None and op.body.required)
            return op.params_type, "parameters", required
        if op.body is not None:
            body_type = op.body.type
            name = "parameters" if body_type.kind == "named" and body_type.name in self.model.objects else "body"
            return t.base(body_type, REQUEST), name, op.body.required
        return None

    def signature(self, op: Operation) -> tuple[list[str], list[str]]:
        """Declarations and call arguments."""
        t = self.types
        decls: list[str] = []
        args: list[str] = []
        for param in op.path_params:
            decls.append(f"{'long' if param.type.kind == 'long' else 'string'} {param.cs_name}")
            args.append(param.cs_name)
        body = self.body_arg(op)
        required_query = [q for q in op.query_args if q.required]
        optional_query = [q for q in op.query_args if not q.required]
        for q in required_query:
            decls.append(f"{t.base(q.type, REQUEST)} {q.cs_name}")
            args.append(q.cs_name)
        if body is not None:
            body_type, body_name, required = body
            decls.append(f"{body_type} {body_name}" if required else f"{body_type}? {body_name} = null")
            args.append(body_name)
        for q in optional_query:
            decls.append(f"{t.nullable(q.type, REQUEST)} {q.cs_name} = null")
            args.append(q.cs_name)
        decls.append("RequestOptions? requestOptions = null")
        decls.append("CancellationToken cancellationToken = default")
        args.append("requestOptions")
        args.append("cancellationToken")
        return decls, args

    def method_docs(self, op: Operation) -> list[str]:
        indent = "        "
        lines = summary(doc_text(op.summary), indent, f"{op.http_method} {op.path}")
        remarks = doc_text(op.description)
        remarks_lines = [f"{indent}/// <remarks>"]
        remarks_lines += [f"{indent}/// {line}" for line in remarks]
        if remarks:
            remarks_lines.append(f"{indent}/// <para/>")
        remarks_lines.append(f"{indent}/// <c>{xml_escape(op.http_method)} {xml_escape(op.path)}</c> (<c>{op.dotted}</c>).")
        if op.idempotency_key:
            remarks_lines.append(f"{indent}/// Accepts an idempotency key: set <see cref=\"RequestOptions.IdempotencyKey\"/>.")
        if op.scope == "application":
            remarks_lines.append(f"{indent}/// Application-scoped: uses <see cref=\"DiditClientOptions.OrganizationId\"/> and <see cref=\"DiditClientOptions.ApplicationId\"/>.")
        remarks_lines.append(f"{indent}/// </remarks>")
        lines += remarks_lines
        for param in op.path_params:
            lines.append(f"{indent}/// <param name=\"{param.cs_name.lstrip('@')}\">{' '.join(doc_text(param.description)) or 'Path parameter <c>' + param.name + '</c>.'}</param>")
        body = self.body_arg(op)
        for q in [q for q in op.query_args if q.required]:
            lines.append(f"{indent}/// <param name=\"{q.cs_name.lstrip('@')}\">{' '.join(doc_text(q.description)) or 'Query parameter <c>' + q.name + '</c>.'}</param>")
        if body is not None:
            lines.append(f"{indent}/// <param name=\"{body[1]}\">The request parameters.</param>")
        for q in [q for q in op.query_args if not q.required]:
            lines.append(f"{indent}/// <param name=\"{q.cs_name.lstrip('@')}\">{' '.join(doc_text(q.description)) or 'Query parameter <c>' + q.name + '</c>.'}</param>")
        lines.append(f"{indent}/// <param name=\"requestOptions\">Per-request overrides of the client options.</param>")
        lines.append(f"{indent}/// <param name=\"cancellationToken\">Cancels the request.</param>")
        if op.deprecated:
            lines.append(f"{indent}[Obsolete({cs_string(obsolete_message(op))})]")
        return lines

    def method(self, op: Operation, raw: bool) -> list[str]:
        indent = "        "
        decls, args = self.signature(op)
        response_type = self.response_type(op)
        name = names.method_name(op.method)
        if raw:
            node_type = names.resource_type_name(op.resource) + "Resource"
            lines = summary(doc_text(op.summary), indent, f"{op.http_method} {op.path}")
            lines.append(f"{indent}/// <remarks>Raw-response variant of <see cref=\"{node_type}.{name}\"/>.</remarks>")
            if op.deprecated:
                lines.append(f"{indent}[Obsolete({cs_string(obsolete_message(op))})]")
        else:
            lines = self.method_docs(op)
        if not raw:
            if response_type is None:
                lines.append(f"{indent}public Task {name}({', '.join(decls)}) =>")
                lines.append(f"{indent}    _raw.{name}({', '.join(args)});")
            else:
                lines.append(f"{indent}public async Task<{response_type}> {name}({', '.join(decls)})")
                lines.append(f"{indent}{{")
                lines.append(f"{indent}    var response = await _raw.{name}({', '.join(args)}).ConfigureAwait(false);")
                lines.append(f"{indent}    return response.Data;")
                lines.append(f"{indent}}}")
            return lines

        returns = "Task<DiditResponse>" if response_type is None else f"Task<DiditResponse<{response_type}>>"
        lines.append(f"{indent}public {returns} {name}({', '.join(decls)})")
        lines.append(f"{indent}{{")
        body = self.body_arg(op)
        if body is not None and body[2]:
            lines.append(f"{indent}    if ({body[1]} is null)")
            lines.append(f"{indent}    {{")
            lines.append(f"{indent}        throw new ArgumentNullException(nameof({body[1]}));")
            lines.append(f"{indent}    }}")
            lines.append("")
        host = "ApiHost.Account" if op.api == "account" else "ApiHost.Verification"
        auth = {"api_key": "AuthKind.ApiKey", "account_token": "AuthKind.AccountToken"}.get(op.auth, "AuthKind.None")
        lines.append(f"{indent}    var request = new ApiRequest(HttpMethods.{METHOD_FIELDS[op.http_method]}, {self.path_expression(op)})")
        lines.append(f"{indent}    {{")
        lines.append(f"{indent}        Host = {host},")
        lines.append(f"{indent}        Auth = {auth},")
        lines.append(f"{indent}        ApplicationScoped = {'true' if op.scope == 'application' else 'false'},")
        lines.append(f"{indent}    }};")
        lines += self.query_lines(op, indent + "    ")
        lines += self.body_lines(op, indent + "    ")
        kind = op.response.kind
        if kind == "none":
            lines.append(f"{indent}    return _pipeline.SendNoContentAsync(request, requestOptions, cancellationToken);")
        elif kind == "binary":
            lines.append(f"{indent}    return _pipeline.SendBinaryAsync(request, requestOptions, cancellationToken);")
        elif kind == "page":
            assert op.response.type is not None
            lines.append(f"{indent}    return _pipeline.SendPageAsync<{self.types.element(op.response.type, RESPONSE)}>(request, requestOptions, cancellationToken);")
        else:
            lines.append(f"{indent}    return _pipeline.SendJsonAsync<{response_type}>(request, requestOptions, cancellationToken);")
        lines.append(f"{indent}}}")
        return lines

    def path_expression(self, op: Operation) -> str:
        parts = re.split(r"(\{[^}]+\})", op.path)
        by_name = {p.name: p for p in op.path_params}
        pieces: list[str] = []
        literal = ""
        for part in parts:
            if part.startswith("{") and part.endswith("}") and part[1:-1] in by_name:
                if literal:
                    pieces.append(cs_string(literal))
                    literal = ""
                param = by_name[part[1:-1]]
                pieces.append(f"PathParameter.Encode({param.cs_name}, \"{param.cs_name.lstrip('@')}\")")
            else:
                literal += part
        if literal:
            pieces.append(cs_string(literal))
        return " + ".join(pieces) if pieces else '""'

    def wire_string(self, expr: str, ref: TypeRef, nullable_static: bool) -> str:
        """Expression converting a scalar value to its wire string (for query strings)."""
        if ref.kind == "named" and ref.name in self.model.enums:
            return f"{expr}?.Value" if nullable_static else f"{expr}.Value"
        return expr

    def query_lines(self, op: Operation, indent: str) -> list[str]:
        lines: list[str] = []
        if not op.query_params:
            return lines
        if op.params_type is not None:
            obj = self.model.objects[op.params_type]
            body = self.body_arg(op)
            holder = body[1] if body else "parameters"
            optional_holder = body is not None and not body[2]
            for prop in obj.props:
                if prop.location != "query":
                    continue
                expr = f"{holder}?.{prop.cs_name}" if optional_holder else f"{holder}.{prop.cs_name}"
                nullable_static = optional_holder or not prop.required
                lines.append(f"{indent}request.Query.Add({cs_string(prop.json_name)}, {self.query_value(expr, prop.type, nullable_static)});")
        for q in op.query_args:
            lines.append(f"{indent}request.Query.Add({cs_string(q.name)}, {self.query_value(q.cs_name, q.type, not q.required)});")
        return lines

    def query_value(self, expr: str, ref: TypeRef, nullable_static: bool) -> str:
        if ref.kind == "list" and ref.item is not None:
            item = ref.item
            access = "?." if nullable_static else "."
            if item.kind == "named" and item.name in self.model.enums:
                return f"{expr}{access}Select(v => v.Value)"
            if item.kind == "string":
                return expr
            if item.kind == "long":
                return expr
            return f"{expr}{access}Select(v => v.ToString())"
        if ref.kind in ("named",) and ref.name in self.model.enums:
            return self.wire_string(expr, ref, nullable_static)
        if ref.kind in ("string", "long", "double", "bool", "datetime"):
            return expr
        return f"{expr}?.ToString()" if nullable_static else f"{expr}.ToString()"

    def body_lines(self, op: Operation, indent: str) -> list[str]:
        body = op.body
        if body is None:
            return []
        arg = self.body_arg(op)
        assert arg is not None
        holder = arg[1]
        required = arg[2]
        lines: list[str] = []
        if body.content_type == "application/json":
            if required:
                lines.append(f"{indent}request.Body = JsonRequestBody.Create({holder});")
            else:
                lines.append(f"{indent}if ({holder} is not null)")
                lines.append(f"{indent}{{")
                lines.append(f"{indent}    request.Body = JsonRequestBody.Create({holder});")
                lines.append(f"{indent}}}")
            return lines

        # multipart/form-data
        assert body.params_type is not None or (body.type.kind == "named" and body.type.name in self.model.objects)
        obj = self.model.objects[body.params_type or body.type.name or ""]
        inner_indent = indent
        if not required:
            lines.append(f"{indent}if ({holder} is not null)")
            lines.append(f"{indent}{{")
            inner_indent = indent + "    "
        lines.append(f"{inner_indent}var form = new MultipartRequestBody();")
        for prop in obj.props:
            if prop.location != "body":
                continue
            lines += self.multipart_prop(holder, prop, obj.role, inner_indent)
        lines.append(f"{inner_indent}request.Body = form;")
        if not required:
            lines.append(f"{indent}}}")
        return lines

    def multipart_prop(self, holder: str, prop: Prop, role: str, indent: str) -> list[str]:
        optional = role == REQUEST and not prop.required
        expr = f"{holder}.{prop.cs_name}.Value" if optional else f"{holder}.{prop.cs_name}"
        call = self.multipart_call(prop.json_name, expr, prop.type, prop.nullable)
        if optional:
            return [f"{indent}if ({holder}.{prop.cs_name}.IsSet)", f"{indent}{{", f"{indent}    {call}", f"{indent}}}"]
        return [f"{indent}{call}"]

    def multipart_call(self, json_name: str, expr: str, ref: TypeRef, nullable_static: bool) -> str:
        name = cs_string(json_name)
        kind = ref.kind
        if kind in ("string", "long", "double", "bool", "datetime", "file"):
            return f"form.Add({name}, {expr});"
        if kind == "named" and ref.name in self.model.enums:
            return f"form.Add({name}, {expr}{'?' if nullable_static else ''}.Value);"
        if kind == "any":
            return f"form.AddAny({name}, {expr});"
        if kind == "list" and ref.item is not None:
            item = ref.item
            access = "?." if nullable_static else "."
            if item.kind in ("string", "file"):
                return f"form.AddEach({name}, {expr});"
            if item.kind == "named" and item.name in self.model.enums:
                return f"form.AddEach({name}, {expr}{access}Select(v => v.Value));"
            if item.kind in ("long", "double", "bool"):
                return f"form.AddEach({name}, {expr}{access}Select(v => JsonSupport.Serialize(v)));"
        return f"form.AddJson({name}, {expr});"

    # ---- client and JSON context --------------------------------------------------------------------------------

    def client_file(self, root: ResourceNode) -> str:
        out = [HEADER, "using Didit.Resources;", "", "namespace Didit", "{"]
        out.append("    public sealed partial class DiditClient")
        out.append("    {")
        children = [root.children[k] for k in sorted(root.children)]
        for child in children:
            out.append(f"        /// <summary>The <c>{'.'.join(child.segments)}</c> resource.</summary>")
            out.append(f"        public {child.type_name} {child.accessor} {{ get; private set; }} = null!;")
            out.append("")
        out.append("        /// <summary>")
        out.append("        /// The same resources, returning <see cref=\"DiditResponse{T}\"/> with the status code, headers and request id")
        out.append("        /// alongside the parsed body.")
        out.append("        /// </summary>")
        out.append("        public DiditRawClient WithRawResponse { get; private set; } = null!;")
        out.append("")
        out.append("        private void InitializeResources()")
        out.append("        {")
        out.append("            WithRawResponse = new DiditRawClient(Pipeline);")
        for child in children:
            out.append(f"            {child.accessor} = new {child.type_name}(WithRawResponse.{child.accessor});")
        out.append("        }")
        out.append("    }")
        out.append("")
        out.append("    /// <summary>The API resources, returning raw HTTP responses. Get it from <see cref=\"DiditClient.WithRawResponse\"/>.</summary>")
        out.append("    public sealed partial class DiditRawClient")
        out.append("    {")
        out.append("        internal DiditRawClient(Internal.HttpPipeline pipeline)")
        out.append("        {")
        for child in children:
            out.append(f"            {child.accessor} = new {child.raw_type_name}(pipeline);")
        out.append("        }")
        for child in children:
            out.append("")
            out.append(f"        /// <summary>The <c>{'.'.join(child.segments)}</c> resource.</summary>")
            out.append(f"        public {child.raw_type_name} {child.accessor} {{ get; }}")
        out.append("    }")
        out.append("}")
        return "\n".join(out) + "\n"

    def context_file(self) -> str:
        t = self.types
        registrations: dict[str, str] = {}

        def register(type_expr: str, prop_name: str | None = None) -> None:
            key = type_expr.replace("?", "")
            if key in registrations:
                return
            registrations[key] = prop_name or ""

        for name in sorted(self.model.objects):
            register(name)
        for name in sorted(self.model.enums):
            register(name)
        for op in self.model.operations:
            if op.response.kind == "json" and op.response.type is not None:
                register(t.base(op.response.type, RESPONSE))
            if op.response.kind == "page" and op.response.type is not None:
                register(f"PageBody<{t.element(op.response.type, RESPONSE)}>")
            if op.body is not None and op.body.content_type == "application/json":
                register(t.base(op.body.type, REQUEST))
        for ref in self.model.optional_inner_types:
            if ref.kind == "file":
                continue
            register(t.base(ref, REQUEST))
        for collection in ("IReadOnlyList<string>", "IReadOnlyList<long>", "IReadOnlyDictionary<string, string>", "IReadOnlyDictionary<string, JsonElement>"):
            register(collection)
        for builtin in ("string", "long", "double", "bool", "DateTimeOffset", "JsonElement", "object"):
            registrations.pop(builtin, None)

        out = [HEADER, "using System;", "using System.Collections.Generic;", "using System.Text.Json;", "using System.Text.Json.Serialization;", "", "namespace Didit.Internal", "{"]
        out.append("    /// <summary>System.Text.Json source generation for every request and response type.</summary>")
        out.append("    [JsonSourceGenerationOptions(GenerationMode = JsonSourceGenerationMode.Metadata)]")
        for key in sorted(registrations):
            if "<" in key:
                prop_name = "Gen" + re.sub(r"[^A-Za-z0-9]", "", key.replace("IReadOnlyList", "ListOf").replace("IReadOnlyDictionary", "MapOf").replace("PageBody", "PageOf"))
                out.append(f"    [JsonSerializable(typeof({key}), TypeInfoPropertyName = \"{prop_name}\")]")
            else:
                out.append(f"    [JsonSerializable(typeof({key}))]")
        out.append("    internal sealed partial class DiditJsonContext : JsonSerializerContext")
        out.append("    {")
        out.append("    }")
        out.append("}")
        return "\n".join(out) + "\n"


def emit(model: Model) -> dict[str, str]:
    return Emitter(model).emit()
